package com.codeguardian.service.ai.impl; import com.codeguardian.service.ai.*; import com.codeguardian.service.ai.config.ModelProviderConfig; import com.codeguardian.service.ai.dto.*; import com.fasterxml.jackson.databind.*; import okhttp3.*; import java.util.*; import java.util.concurrent.TimeUnit;
public class OpenAICompatibleProvider implements AIModelProvider {protected final ModelProviderConfig config;protected final ObjectMapper json;public OpenAICompatibleProvider(ModelProviderConfig c,ObjectMapper j){config=c;json=j;} public String getProviderName(){return config.getProviderName();}public boolean isAvailable(){return Boolean.TRUE.equals(config.getEnabled())&&config.getBaseUrl()!=null&&!config.getBaseUrl().isBlank();}public AIModelResponse chat(AIModelRequest req){if(!isAvailable())throw new IllegalStateException("AI provider is not configured: "+getProviderName());try{String endpoint=config.getBaseUrl().replaceAll("/$","");if(!endpoint.endsWith("/chat/completions"))endpoint+="/v1/chat/completions";Map<String,Object> body=new HashMap<>();body.put("model",req.getModel()==null?config.getDefaultModel():req.getModel());body.put("messages",req.getMessages());body.put("temperature",req.getTemperature());Request.Builder rb=new Request.Builder().url(endpoint).header("Content-Type","application/json");if(config.getApiKey()!=null&&!config.getApiKey().isBlank())rb.header("Authorization","Bearer "+config.getApiKey());Request http=rb.post(RequestBody.create(json.writeValueAsString(body),MediaType.get("application/json"))).build();try(Response res=new OkHttpClient.Builder().callTimeout(config.getTimeout(),TimeUnit.SECONDS).build().newCall(http).execute()){if(!res.isSuccessful())throw new IllegalStateException("AI request failed: "+res.code());JsonNode root=json.readTree(Objects.requireNonNull(res.body()).string());return AIModelResponse.builder().content(root.path("choices").path(0).path("message").path("content").asText()).model(root.path("model").asText()).usageTokens(root.path("usage").path("total_tokens").asInt()).finishReason(root.path("choices").path(0).path("finish_reason").asText()).build();}}catch(Exception e){throw new IllegalStateException("AI request failed",e);}}}
